CREATE TEMP TABLE reviewed_before AS SELECT house_id,state,version FROM noble_house_sheets;
UPDATE noble_house_sheets SET version=version+1 WHERE house_id='ashkar';
\ir ../drizzle/migrations/0042_reconcile_house_workbooks.sql
SELECT pg_temp.assert((SELECT status='needs_review' FROM noble_house_workbook_imports WHERE house_key='ashkar'),'version change blocks reviewed snapshot');
SELECT pg_temp.assert((SELECT count(*)=5 FROM noble_house_workbook_imports WHERE status='applied'),'five matching snapshots imported');
UPDATE noble_house_sheets SET version=4 WHERE house_id='ashkar';
\ir ../drizzle/migrations/0042_reconcile_house_workbooks.sql
SELECT pg_temp.assert((SELECT count(*)=6 FROM noble_house_workbook_imports WHERE status='applied'),'all six reviewed snapshots imported');
SELECT pg_temp.assert((SELECT bool_and(s.state->'court'=b.state->'court') FROM noble_house_sheets s JOIN reviewed_before b USING(house_id)),'preserve existing court IDs and links');
SELECT pg_temp.assert((SELECT s.state->'vassals'=b.state->'vassals' FROM noble_house_sheets s JOIN reviewed_before b USING(house_id) WHERE house_id='ashkar'),'preserve approved Qazir');
SELECT pg_temp.assert((SELECT count(*)=1 FROM noble_house_sheets, LATERAL jsonb_array_elements(state->'holdings') h WHERE house_id='ashkar' AND h->>'category'='vassal'),'Qazir allocated only once');
SELECT pg_temp.assert((SELECT sum((c->>'amount')::integer)=20 FROM noble_house_sheets, LATERAL jsonb_array_elements(state->'holdings') h, LATERAL jsonb_array_elements(h->'costs') c WHERE house_id='ashkar' AND h->>'category'='vassal' AND c->>'resource'='power'),'Qazir retains 20 Power cost');
SELECT pg_temp.assert((SELECT bool_and(s.version=b.version+1) FROM noble_house_sheets s JOIN reviewed_before b USING(house_id)),'each successful import increments version once');
SELECT pg_temp.assert((SELECT count(*)=6 FROM noble_house_ledger WHERE action='Conciliação das fichas 29/10/2026'),'audit every reviewed import');
SELECT pg_temp.assert((SELECT bool_and(l.before_state=b.state) FROM noble_house_ledger l JOIN reviewed_before b USING(house_id)),'backup exact originals');
\ir ../drizzle/migrations/0042_reconcile_house_workbooks.sql
SELECT pg_temp.assert((SELECT count(*)=6 FROM noble_house_ledger WHERE action='Conciliação das fichas 29/10/2026'),'replay does not add ledger entries');
ROLLBACK;
